// 257-entry Unsigned Newton-Raphson Reciprocal Table for GTE Division
// Generated by: unr_table[i] = max(0, (0x40000 / (i + 0x100) + 1) / 2 - 0x101)
static const uint8_t gte_unr_table[257] = {
    0xFF, 0xFD, 0xFB, 0xF9, 0xF7, 0xF5, 0xF3, 0xF1, 0xEF, 0xEE, 0xEC, 0xEA, 0xE8, 0xE6, 0xE4, 0xE3,
    0xE1, 0xDF, 0xDD, 0xDC, 0xDA, 0xD8, 0xD6, 0xD5, 0xD3, 0xD1, 0xD0, 0xCE, 0xCD, 0xCB, 0xC9, 0xC8,
    0xC6, 0xC5, 0xC3, 0xC1, 0xC0, 0xBE, 0xBD, 0xBB, 0xBA, 0xB8, 0xB7, 0xB5, 0xB4, 0xB2, 0xB1, 0xB0,
    0xAE, 0xAD, 0xAB, 0xAA, 0xA9, 0xA7, 0xA6, 0xA4, 0xA3, 0xA2, 0xA0, 0x9F, 0x9E, 0x9C, 0x9B, 0x9A,
    0x99, 0x97, 0x96, 0x95, 0x94, 0x92, 0x91, 0x90, 0x8F, 0x8D, 0x8C, 0x8B, 0x8A, 0x89, 0x87, 0x86,
    0x85, 0x84, 0x83, 0x82, 0x81, 0x7F, 0x7E, 0x7D, 0x7C, 0x7B, 0x7A, 0x79, 0x78, 0x77, 0x75, 0x74,
    0x73, 0x72, 0x71, 0x70, 0x6F, 0x6E, 0x6D, 0x6C, 0x6B, 0x6A, 0x69, 0x68, 0x67, 0x66, 0x65, 0x64,
    0x63, 0x62, 0x61, 0x60, 0x5F, 0x5E, 0x5D, 0x5D, 0x5C, 0x5B, 0x5A, 0x59, 0x58, 0x57, 0x56, 0x55,
    0x54, 0x53, 0x53, 0x52, 0x51, 0x50, 0x4F, 0x4E, 0x4D, 0x4D, 0x4C, 0x4B, 0x4A, 0x49, 0x48, 0x48,
    0x47, 0x46, 0x45, 0x44, 0x43, 0x43, 0x42, 0x41, 0x40, 0x3F, 0x3F, 0x3E, 0x3D, 0x3C, 0x3C, 0x3B,
    0x3A, 0x39, 0x39, 0x38, 0x37, 0x36, 0x36, 0x35, 0x34, 0x33, 0x33, 0x32, 0x31, 0x31, 0x30, 0x2F,
    0x2E, 0x2E, 0x2D, 0x2C, 0x2C, 0x2B, 0x2A, 0x2A, 0x29, 0x28, 0x28, 0x27, 0x26, 0x26, 0x25, 0x24,
    0x24, 0x23, 0x22, 0x22, 0x21, 0x20, 0x20, 0x1F, 0x1E, 0x1E, 0x1D, 0x1D, 0x1C, 0x1B, 0x1B, 0x1A,
    0x19, 0x19, 0x18, 0x18, 0x17, 0x16, 0x16, 0x15, 0x15, 0x14, 0x14, 0x13, 0x12, 0x12, 0x11, 0x11,
    0x10, 0x0F, 0x0F, 0x0E, 0x0E, 0x0D, 0x0D, 0x0C, 0x0C, 0x0B, 0x0A, 0x0A, 0x09, 0x09, 0x08, 0x08,
    0x07, 0x07, 0x06, 0x06, 0x05, 0x05, 0x04, 0x04, 0x03, 0x03, 0x02, 0x02, 0x01, 0x01, 0x00, 0x00,
    0x00
};

static inline void check_mac1_overflow(PS1GTE* gte, int64_t mac) {
    if (mac < -0x80000000000LL) gte->flag |= (1u << 30);
    else if (mac > 0x7FFFFFFFFFFLL) gte->flag |= (1u << 27);
}

static inline void check_mac2_overflow(PS1GTE* gte, int64_t mac) {
    if (mac < -0x80000000000LL) gte->flag |= (1u << 29);
    else if (mac > 0x7FFFFFFFFFFLL) gte->flag |= (1u << 26);
}

static inline void check_mac3_overflow(PS1GTE* gte, int64_t mac) {
    if (mac < -0x80000000000LL) gte->flag |= (1u << 28);
    else if (mac > 0x7FFFFFFFFFFLL) gte->flag |= (1u << 25);
}

static inline void check_mac0_overflow(PS1GTE* gte, int64_t mac) {
    if (mac < -0x80000000LL) gte->flag |= (1u << 16);
    else if (mac > 0x7FFFFFFFLL) gte->flag |= (1u << 15);
}

static inline int16_t clamp_ir1(PS1GTE* gte, int64_t val, bool lm) {
    int64_t min_val = lm ? 0 : -0x8000;
    int64_t max_val = 0x7FFF;
    if (val < min_val) {
        gte->flag |= (1u << 24);
        return (int16_t)min_val;
    } else if (val > max_val) {
        gte->flag |= (1u << 24);
        return (int16_t)max_val;
    }
    return (int16_t)val;
}

static inline int16_t clamp_ir2(PS1GTE* gte, int64_t val, bool lm) {
    int64_t min_val = lm ? 0 : -0x8000;
    int64_t max_val = 0x7FFF;
    if (val < min_val) {
        gte->flag |= (1u << 23);
        return (int16_t)min_val;
    } else if (val > max_val) {
        gte->flag |= (1u << 23);
        return (int16_t)max_val;
    }
    return (int16_t)val;
}

static inline int16_t clamp_ir3(PS1GTE* gte, int64_t val, bool lm) {
    int64_t min_val = lm ? 0 : -0x8000;
    int64_t max_val = 0x7FFF;
    if (val < min_val) {
        gte->flag |= (1u << 22);
        return (int16_t)min_val;
    } else if (val > max_val) {
        gte->flag |= (1u << 22);
        return (int16_t)max_val;
    }
    return (int16_t)val;
}

static inline int16_t clamp_ir0(PS1GTE* gte, int64_t val) {
    if (val < 0) {
        gte->flag |= (1u << 12);
        return 0;
    } else if (val > 0x1000) {
        gte->flag |= (1u << 12);
        return 0x1000;
    }
    return (int16_t)val;
}

static inline uint8_t clamp_color_r(PS1GTE* gte, int64_t val) {
    if (val < 0) {
        gte->flag |= (1u << 21);
        return 0;
    } else if (val > 255) {
        gte->flag |= (1u << 21);
        return 255;
    }
    return (uint8_t)val;
}

static inline uint8_t clamp_color_g(PS1GTE* gte, int64_t val) {
    if (val < 0) {
        gte->flag |= (1u << 20);
        return 0;
    } else if (val > 255) {
        gte->flag |= (1u << 20);
        return 255;
    }
    return (uint8_t)val;
}

static inline uint8_t clamp_color_b(PS1GTE* gte, int64_t val) {
    if (val < 0) {
        gte->flag |= (1u << 19);
        return 0;
    } else if (val > 255) {
        gte->flag |= (1u << 19);
        return 255;
    }
    return (uint8_t)val;
}

static inline void push_color_fifo(PS1GTE* gte, uint8_t r, uint8_t g, uint8_t b, uint8_t code) {
    gte->rgb[0][0] = gte->rgb[1][0];
    gte->rgb[0][1] = gte->rgb[1][1];
    gte->rgb[0][2] = gte->rgb[1][2];
    gte->rgb[0][3] = gte->rgb[1][3];

    gte->rgb[1][0] = gte->rgb[2][0];
    gte->rgb[1][1] = gte->rgb[2][1];
    gte->rgb[1][2] = gte->rgb[2][2];
    gte->rgb[1][3] = gte->rgb[2][3];

    gte->rgb[2][0] = r;
    gte->rgb[2][1] = g;
    gte->rgb[2][2] = b;
    gte->rgb[2][3] = code;
}

static inline void push_sxy_fifo(PS1GTE* gte, int16_t sx, int16_t sy) {
    gte->sxy[0][0] = gte->sxy[1][0];
    gte->sxy[0][1] = gte->sxy[1][1];
    gte->sxy[1][0] = gte->sxy[2][0];
    gte->sxy[1][1] = gte->sxy[2][1];
    gte->sxy[2][0] = sx;
    gte->sxy[2][1] = sy;
}

static inline void push_sz_fifo(PS1GTE* gte, uint16_t sz) {
    gte->sz[0] = gte->sz[1];
    gte->sz[1] = gte->sz[2];
    gte->sz[2] = gte->sz[3];
    gte->sz[3] = sz;
}

static uint32_t gte_unr_divide(PS1GTE* gte, uint32_t h, uint16_t sz3) {
    if (h < (uint32_t)sz3 * 2) {
        if (sz3 == 0) {
            gte->flag |= (1u << 17);
            return 0x1FFFF;
        }
        int z = __builtin_clz((uint32_t)sz3) - 16; // 16-bit leading zeros (0..15)
        uint64_t n = (uint64_t)h << z;
        uint64_t d = (uint64_t)sz3 << z;
        uint32_t idx = (uint32_t)((d - 0x7FC0) >> 7);
        if (idx > 0x100) idx = 0x100;
        uint64_t u = (uint64_t)gte_unr_table[idx] + 0x101;
        d = ((0x2000080ULL - (d * u)) >> 8);
        d = ((0x0000080ULL + (d * u)) >> 8);
        uint32_t res = (uint32_t)(((n * d) + 0x8000ULL) >> 16);
        if (res > 0x1FFFF) res = 0x1FFFF;
        return res;
    } else {
        gte->flag |= (1u << 17);
        return 0x1FFFF;
    }
}

void ps1_gte_init(PS1GTE* gte) {
    memset(gte, 0, sizeof(PS1GTE));
    gte->h = 240;
}

void ps1_gte_reset(PS1GTE* gte) {
    memset(gte, 0, sizeof(PS1GTE));
    gte->h = 240;
}

uint32_t ps1_gte_get_data(PS1GTE* gte, uint32_t reg) {
    switch (reg) {
        case 0: return (uint16_t)gte->v[0][0] | ((uint32_t)(uint16_t)gte->v[0][1] << 16);
        case 1: return (uint32_t)(int32_t)gte->v[0][2];
        case 2: return (uint16_t)gte->v[1][0] | ((uint32_t)(uint16_t)gte->v[1][1] << 16);
        case 3: return (uint32_t)(int32_t)gte->v[1][2];
        case 4: return (uint16_t)gte->v[2][0] | ((uint32_t)(uint16_t)gte->v[2][1] << 16);
        case 5: return (uint32_t)(int32_t)gte->v[2][2];
        case 6: return *(uint32_t*)gte->rgbc;
        case 7: return (uint32_t)gte->otz;
        case 8: return (uint32_t)(int32_t)gte->ir[0];
        case 9: return (uint32_t)(int32_t)gte->ir[1];
        case 10: return (uint32_t)(int32_t)gte->ir[2];
        case 11: return (uint32_t)(int32_t)gte->ir[3];
        case 12: return (uint16_t)gte->sxy[0][0] | ((uint32_t)(uint16_t)gte->sxy[0][1] << 16);
        case 13: return (uint16_t)gte->sxy[1][0] | ((uint32_t)(uint16_t)gte->sxy[1][1] << 16);
        case 14: return (uint16_t)gte->sxy[2][0] | ((uint32_t)(uint16_t)gte->sxy[2][1] << 16);
        case 15: return (uint16_t)gte->sxy[2][0] | ((uint32_t)(uint16_t)gte->sxy[2][1] << 16); // SXYP returns SXY2
        case 16: return (uint32_t)gte->sz[0];
        case 17: return (uint32_t)gte->sz[1];
        case 18: return (uint32_t)gte->sz[2];
        case 19: return (uint32_t)gte->sz[3];
        case 20: return *(uint32_t*)gte->rgb[0];
        case 21: return *(uint32_t*)gte->rgb[1];
        case 22: return *(uint32_t*)gte->rgb[2];
        case 23: return 0;
        case 24: return (uint32_t)gte->mac[0];
        case 25: return (uint32_t)gte->mac[1];
        case 26: return (uint32_t)gte->mac[2];
        case 27: return (uint32_t)gte->mac[3];
        case 28: return gte->irgb;
        case 29: {
            uint32_t r = (gte->ir[1] < 0) ? 0 : (gte->ir[1] > 0x1F * 0x80 ? 0x1F : (uint32_t)(gte->ir[1] / 0x80));
            uint32_t g = (gte->ir[2] < 0) ? 0 : (gte->ir[2] > 0x1F * 0x80 ? 0x1F : (uint32_t)(gte->ir[2] / 0x80));
            uint32_t b = (gte->ir[3] < 0) ? 0 : (gte->ir[3] > 0x1F * 0x80 ? 0x1F : (uint32_t)(gte->ir[3] / 0x80));
            return r | (g << 5) | (b << 10);
        }
        case 30: return (uint32_t)gte->lzcs;
        case 31: return (uint32_t)gte->lzcr;
        default: return 0;
    }
}

void ps1_gte_set_data(PS1GTE* gte, uint32_t reg, uint32_t val) {
    switch (reg) {
        case 0:
            gte->v[0][0] = (int16_t)(val & 0xFFFF);
            gte->v[0][1] = (int16_t)(val >> 16);
            break;
        case 1:
            gte->v[0][2] = (int16_t)(val & 0xFFFF);
            break;
        case 2:
            gte->v[1][0] = (int16_t)(val & 0xFFFF);
            gte->v[1][1] = (int16_t)(val >> 16);
            break;
        case 3:
            gte->v[1][2] = (int16_t)(val & 0xFFFF);
            break;
        case 4:
            gte->v[2][0] = (int16_t)(val & 0xFFFF);
            gte->v[2][1] = (int16_t)(val >> 16);
            break;
        case 5:
            gte->v[2][2] = (int16_t)(val & 0xFFFF);
            break;
        case 6: *(uint32_t*)gte->rgbc = val; break;
        case 7: gte->otz = (uint16_t)val; break;
        case 8: gte->ir[0] = (int16_t)val; break;
        case 9: gte->ir[1] = (int16_t)val; break;
        case 10: gte->ir[2] = (int16_t)val; break;
        case 11: gte->ir[3] = (int16_t)val; break;
        case 12:
            gte->sxy[0][0] = (int16_t)(val & 0xFFFF);
            gte->sxy[0][1] = (int16_t)(val >> 16);
            break;
        case 13:
            gte->sxy[1][0] = (int16_t)(val & 0xFFFF);
            gte->sxy[1][1] = (int16_t)(val >> 16);
            break;
        case 14:
            gte->sxy[2][0] = (int16_t)(val & 0xFFFF);
            gte->sxy[2][1] = (int16_t)(val >> 16);
            break;
        case 15:
            // SXYP push FIFO
            push_sxy_fifo(gte, (int16_t)(val & 0xFFFF), (int16_t)(val >> 16));
            break;
        case 16: gte->sz[0] = (uint16_t)val; break;
        case 17: gte->sz[1] = (uint16_t)val; break;
        case 18: gte->sz[2] = (uint16_t)val; break;
        case 19: gte->sz[3] = (uint16_t)val; break;
        case 20: *(uint32_t*)gte->rgb[0] = val; break;
        case 21: *(uint32_t*)gte->rgb[1] = val; break;
        case 22: *(uint32_t*)gte->rgb[2] = val; break;
        case 24: gte->mac[0] = (int32_t)val; break;
        case 25: gte->mac[1] = (int32_t)val; break;
        case 26: gte->mac[2] = (int32_t)val; break;
        case 27: gte->mac[3] = (int32_t)val; break;
        case 28:
            gte->ir[1] = (int16_t)(((val >> 0) & 0x1F) * 0x80);
            gte->ir[2] = (int16_t)(((val >> 5) & 0x1F) * 0x80);
            gte->ir[3] = (int16_t)(((val >> 10) & 0x1F) * 0x80);
            gte->irgb = val;
            break;
        case 30:
            gte->lzcs = (int32_t)val;
            if (val == 0 || val == 0xFFFFFFFF) {
                gte->lzcr = 32;
            } else if ((int32_t)val < 0) {
                gte->lzcr = __builtin_clz(~val);
            } else {
                gte->lzcr = __builtin_clz(val);
            }
            break;
        case 31: gte->lzcr = (int32_t)val; break;
    }
}

uint32_t ps1_gte_get_ctrl(PS1GTE* gte, uint32_t reg) {
    switch (reg) {
        case 0: return (uint16_t)gte->rot_matrix[0][0] | ((uint32_t)(uint16_t)gte->rot_matrix[0][1] << 16);
        case 1: return (uint16_t)gte->rot_matrix[0][2] | ((uint32_t)(uint16_t)gte->rot_matrix[1][0] << 16);
        case 2: return (uint16_t)gte->rot_matrix[1][1] | ((uint32_t)(uint16_t)gte->rot_matrix[1][2] << 16);
        case 3: return (uint16_t)gte->rot_matrix[2][0] | ((uint32_t)(uint16_t)gte->rot_matrix[2][1] << 16);
        case 4: return (uint32_t)(int32_t)gte->rot_matrix[2][2];
        case 5: return (uint32_t)gte->trans_vector[0];
        case 6: return (uint32_t)gte->trans_vector[1];
        case 7: return (uint32_t)gte->trans_vector[2];
        case 8: return (uint16_t)gte->light_matrix[0][0] | ((uint32_t)(uint16_t)gte->light_matrix[0][1] << 16);
        case 9: return (uint16_t)gte->light_matrix[0][2] | ((uint32_t)(uint16_t)gte->light_matrix[1][0] << 16);
        case 10: return (uint16_t)gte->light_matrix[1][1] | ((uint32_t)(uint16_t)gte->light_matrix[1][2] << 16);
        case 11: return (uint16_t)gte->light_matrix[2][0] | ((uint32_t)(uint16_t)gte->light_matrix[2][1] << 16);
        case 12: return (uint32_t)(int32_t)gte->light_matrix[2][2];
        case 13: return (uint32_t)gte->back_color[0];
        case 14: return (uint32_t)gte->back_color[1];
        case 15: return (uint32_t)gte->back_color[2];
        case 16: return (uint16_t)gte->color_matrix[0][0] | ((uint32_t)(uint16_t)gte->color_matrix[0][1] << 16);
        case 17: return (uint16_t)gte->color_matrix[0][2] | ((uint32_t)(uint16_t)gte->color_matrix[1][0] << 16);
        case 18: return (uint16_t)gte->color_matrix[1][1] | ((uint32_t)(uint16_t)gte->color_matrix[1][2] << 16);
        case 19: return (uint16_t)gte->color_matrix[2][0] | ((uint32_t)(uint16_t)gte->color_matrix[2][1] << 16);
        case 20: return (uint32_t)(int32_t)gte->color_matrix[2][2];
        case 21: return (uint32_t)gte->far_color[0];
        case 22: return (uint32_t)gte->far_color[1];
        case 23: return (uint32_t)gte->far_color[2];
        case 24: return (uint32_t)gte->offset_x;
        case 25: return (uint32_t)gte->offset_y;
        case 26: return (uint32_t)(int32_t)(int16_t)gte->h; // hardware bug: sign-extended
        case 27: return (uint32_t)(int32_t)gte->dqa;
        case 28: return (uint32_t)gte->dqb;
        case 29: return (uint32_t)(int32_t)gte->zsf3;
        case 30: return (uint32_t)(int32_t)gte->zsf4;
        case 31: return gte->flag;
        default: return 0;
    }
}

void ps1_gte_set_ctrl(PS1GTE* gte, uint32_t reg, uint32_t val) {
    switch (reg) {
        case 0:
            gte->rot_matrix[0][0] = (int16_t)(val & 0xFFFF);
            gte->rot_matrix[0][1] = (int16_t)(val >> 16);
            break;
        case 1:
            gte->rot_matrix[0][2] = (int16_t)(val & 0xFFFF);
            gte->rot_matrix[1][0] = (int16_t)(val >> 16);
            break;
        case 2:
            gte->rot_matrix[1][1] = (int16_t)(val & 0xFFFF);
            gte->rot_matrix[1][2] = (int16_t)(val >> 16);
            break;
        case 3:
            gte->rot_matrix[2][0] = (int16_t)(val & 0xFFFF);
            gte->rot_matrix[2][1] = (int16_t)(val >> 16);
            break;
        case 4:
            gte->rot_matrix[2][2] = (int16_t)(val & 0xFFFF);
            break;
        case 5: gte->trans_vector[0] = (int32_t)val; break;
        case 6: gte->trans_vector[1] = (int32_t)val; break;
        case 7: gte->trans_vector[2] = (int32_t)val; break;
        case 8:
            gte->light_matrix[0][0] = (int16_t)(val & 0xFFFF);
            gte->light_matrix[0][1] = (int16_t)(val >> 16);
            break;
        case 9:
            gte->light_matrix[0][2] = (int16_t)(val & 0xFFFF);
            gte->light_matrix[1][0] = (int16_t)(val >> 16);
            break;
        case 10:
            gte->light_matrix[1][1] = (int16_t)(val & 0xFFFF);
            gte->light_matrix[1][2] = (int16_t)(val >> 16);
            break;
        case 11:
            gte->light_matrix[2][0] = (int16_t)(val & 0xFFFF);
            gte->light_matrix[2][1] = (int16_t)(val >> 16);
            break;
        case 12:
            gte->light_matrix[2][2] = (int16_t)(val & 0xFFFF);
            break;
        case 13: gte->back_color[0] = (int32_t)val; break;
        case 14: gte->back_color[1] = (int32_t)val; break;
        case 15: gte->back_color[2] = (int32_t)val; break;
        case 16:
            gte->color_matrix[0][0] = (int16_t)(val & 0xFFFF);
            gte->color_matrix[0][1] = (int16_t)(val >> 16);
            break;
        case 17:
            gte->color_matrix[0][2] = (int16_t)(val & 0xFFFF);
            gte->color_matrix[1][0] = (int16_t)(val >> 16);
            break;
        case 18:
            gte->color_matrix[1][1] = (int16_t)(val & 0xFFFF);
            gte->color_matrix[1][2] = (int16_t)(val >> 16);
            break;
        case 19:
            gte->color_matrix[2][0] = (int16_t)(val & 0xFFFF);
            gte->color_matrix[2][1] = (int16_t)(val >> 16);
            break;
        case 20:
            gte->color_matrix[2][2] = (int16_t)(val & 0xFFFF);
            break;
        case 21: gte->far_color[0] = (int32_t)val; break;
        case 22: gte->far_color[1] = (int32_t)val; break;
        case 23: gte->far_color[2] = (int32_t)val; break;
        case 24: gte->offset_x = (int32_t)val; break;
        case 25: gte->offset_y = (int32_t)val; break;
        case 26: gte->h = (uint16_t)val; break;
        case 27: gte->dqa = (int16_t)val; break;
        case 28: gte->dqb = (int32_t)val; break;
        case 29: gte->zsf3 = (int16_t)val; break;
        case 30: gte->zsf4 = (int16_t)val; break;
        case 31:
            // Writing to FLAG only updates bits 30..12
            gte->flag = (val & 0x7FFFF000);
            if (gte->flag & 0x7F87E000) gte->flag |= (1u << 31);
            break;
    }
}

// Transform single vertex helper for RTPS and RTPT
static void gte_rtps_vertex(PS1GTE* gte, int v_idx, bool sf, bool is_last_vertex) {
    int16_t vx = gte->v[v_idx][0];
    int16_t vy = gte->v[v_idx][1];
    int16_t vz = gte->v[v_idx][2];

    int64_t mac1 = ((int64_t)gte->trans_vector[0] << 12) +
                   (int64_t)gte->rot_matrix[0][0] * vx +
                   (int64_t)gte->rot_matrix[0][1] * vy +
                   (int64_t)gte->rot_matrix[0][2] * vz;
    int64_t mac2 = ((int64_t)gte->trans_vector[1] << 12) +
                   (int64_t)gte->rot_matrix[1][0] * vx +
                   (int64_t)gte->rot_matrix[1][1] * vy +
                   (int64_t)gte->rot_matrix[1][2] * vz;
    int64_t mac3 = ((int64_t)gte->trans_vector[2] << 12) +
                   (int64_t)gte->rot_matrix[2][0] * vx +
                   (int64_t)gte->rot_matrix[2][1] * vy +
                   (int64_t)gte->rot_matrix[2][2] * vz;

    check_mac1_overflow(gte, mac1);
    check_mac2_overflow(gte, mac2);
    check_mac3_overflow(gte, mac3);

    gte->mac[1] = (int32_t)(mac1 >> (sf ? 12 : 0));
    gte->mac[2] = (int32_t)(mac2 >> (sf ? 12 : 0));
    gte->mac[3] = (int32_t)(mac3 >> (sf ? 12 : 0));

    gte->ir[1] = clamp_ir1(gte, gte->mac[1], false);
    gte->ir[2] = clamp_ir2(gte, gte->mac[2], false);

    // IR3 Quirk in RTPS/RTPT: flag 22 is checked against MAC3 >> 12 regardless of sf
    int64_t mac3_sar12 = mac3 >> 12;
    if (mac3_sar12 < -0x8000 || mac3_sar12 > 0x7FFF) {
        gte->flag |= (1u << 22);
    }
    if (gte->mac[3] < -0x8000) gte->ir[3] = -0x8000;
    else if (gte->mac[3] > 0x7FFF) gte->ir[3] = 0x7FFF;
    else gte->ir[3] = (int16_t)gte->mac[3];

    // SZ3 = MAC3 >> ((1 - sf) * 12) saturated to 0..0xFFFF
    int64_t sz3_raw = (int64_t)gte->mac[3] >> ((1 - (sf ? 1 : 0)) * 12);
    uint16_t sz3;
    if (sz3_raw < 0) {
        sz3 = 0;
        gte->flag |= (1u << 18);
    } else if (sz3_raw > 0xFFFF) {
        sz3 = 0xFFFF;
        gte->flag |= (1u << 18);
    } else {
        sz3 = (uint16_t)sz3_raw;
    }
    push_sz_fifo(gte, sz3);

    // Perspective division
    uint32_t n = gte_unr_divide(gte, gte->h, sz3);

    // SX
    int64_t mac0_x = (int64_t)n * gte->ir[1] + gte->offset_x;
    check_mac0_overflow(gte, mac0_x);
    int64_t sx = mac0_x >> 16;
    if (sx < -0x400) {
        sx = -0x400;
        gte->flag |= (1u << 14);
    } else if (sx > 0x3FF) {
        sx = 0x3FF;
        gte->flag |= (1u << 14);
    }

    // SY
    int64_t mac0_y = (int64_t)n * gte->ir[2] + gte->offset_y;
    check_mac0_overflow(gte, mac0_y);
    int64_t sy = mac0_y >> 16;
    if (sy < -0x400) {
        sy = -0x400;
        gte->flag |= (1u << 13);
    } else if (sy > 0x3FF) {
        sy = 0x3FF;
        gte->flag |= (1u << 13);
    }

    push_sxy_fifo(gte, (int16_t)sx, (int16_t)sy);

    // Depth cueing: only on the last vertex
    if (is_last_vertex) {
        int64_t mac0_d = (int64_t)n * gte->dqa + gte->dqb;
        check_mac0_overflow(gte, mac0_d);
        gte->mac[0] = (int32_t)mac0_d;
        gte->ir[0] = clamp_ir0(gte, mac0_d >> 12);
    }
}

// RTPS: Perspective Transform Single
void ps1_gte_rtps(PS1GTE* gte, uint32_t instruction) {
    gte->flag = 0;
    bool sf = (instruction & (1 << 19)) != 0;
    gte_rtps_vertex(gte, 0, sf, true);
    if (gte->flag & 0x7F87E000) gte->flag |= (1u << 31);
}

// RTPT: Perspective Transform Triple
void ps1_gte_rtpt(PS1GTE* gte, uint32_t instruction) {
    gte->flag = 0;
    bool sf = (instruction & (1 << 19)) != 0;
    gte_rtps_vertex(gte, 0, sf, false);
    gte_rtps_vertex(gte, 1, sf, false);
    gte_rtps_vertex(gte, 2, sf, true);
    if (gte->flag & 0x7F87E000) gte->flag |= (1u << 31);
}

// NCLIP: Normal Clip
void ps1_gte_nclip(PS1GTE* gte) {
    gte->flag = 0;
    int64_t x0 = gte->sxy[0][0];
    int64_t y0 = gte->sxy[0][1];
    int64_t x1 = gte->sxy[1][0];
    int64_t y1 = gte->sxy[1][1];
    int64_t x2 = gte->sxy[2][0];
    int64_t y2 = gte->sxy[2][1];

    int64_t mac0 = x0 * (y1 - y2) + x1 * (y2 - y0) + x2 * (y0 - y1);
    check_mac0_overflow(gte, mac0);
    gte->mac[0] = (int32_t)mac0;

    if (gte->flag & 0x7F87E000) gte->flag |= (1u << 31);
}

// AVSZ3 / AVSZ4: Average Z
void ps1_gte_avsz3(PS1GTE* gte) {
    gte->flag = 0;
    int64_t mac0 = (int64_t)gte->zsf3 * (gte->sz[1] + gte->sz[2] + gte->sz[3]);
    check_mac0_overflow(gte, mac0);
    gte->mac[0] = (int32_t)mac0;

    int64_t otz = mac0 >> 12;
    if (otz < 0) {
        gte->otz = 0;
        gte->flag |= (1u << 18);
    } else if (otz > 0xFFFF) {
        gte->otz = 0xFFFF;
        gte->flag |= (1u << 18);
    } else {
        gte->otz = (uint16_t)otz;
    }

    if (gte->flag & 0x7F87E000) gte->flag |= (1u << 31);
}

void ps1_gte_avsz4(PS1GTE* gte) {
    gte->flag = 0;
    int64_t mac0 = (int64_t)gte->zsf4 * (gte->sz[0] + gte->sz[1] + gte->sz[2] + gte->sz[3]);
    check_mac0_overflow(gte, mac0);
    gte->mac[0] = (int32_t)mac0;

    int64_t otz = mac0 >> 12;
    if (otz < 0) {
        gte->otz = 0;
        gte->flag |= (1u << 18);
    } else if (otz > 0xFFFF) {
        gte->otz = 0xFFFF;
        gte->flag |= (1u << 18);
    } else {
        gte->otz = (uint16_t)otz;
    }

    if (gte->flag & 0x7F87E000) gte->flag |= (1u << 31);
}

// MVMVA: Matrix Multiply Vector Add
void ps1_gte_mvmva(PS1GTE* gte, uint32_t instruction) {
    gte->flag = 0;
    bool sf = (instruction & (1 << 19)) != 0;
    int mx_sel = (instruction >> 17) & 3;
    int v_sel  = (instruction >> 15) & 3;
    int cv_sel = (instruction >> 13) & 3;
    bool lm    = (instruction & (1 << 10)) != 0;

    int16_t m[3][3];
    if (mx_sel == 0) {
        memcpy(m, gte->rot_matrix, sizeof(m));
    } else if (mx_sel == 1) {
        memcpy(m, gte->light_matrix, sizeof(m));
    } else if (mx_sel == 2) {
        memcpy(m, gte->color_matrix, sizeof(m));
    } else {
        int16_t r_10 = (int16_t)gte->rgbc[0] * 0x10;
        m[0][0] = -r_10; m[0][1] = r_10; m[0][2] = gte->ir[0];
        m[1][0] = gte->rot_matrix[0][2]; m[1][1] = gte->rot_matrix[0][2]; m[1][2] = gte->rot_matrix[0][2];
        m[2][0] = gte->rot_matrix[1][1]; m[2][1] = gte->rot_matrix[1][1]; m[2][2] = gte->rot_matrix[1][1];
    }

    int16_t vx, vy, vz;
    if (v_sel < 3) {
        vx = gte->v[v_sel][0];
        vy = gte->v[v_sel][1];
        vz = gte->v[v_sel][2];
    } else {
        vx = gte->ir[1];
        vy = gte->ir[2];
        vz = gte->ir[3];
    }

    int64_t tx = 0, ty = 0, tz = 0;
    bool cv2_bug = (cv_sel == 2);
    if (cv_sel == 0) {
        tx = (int64_t)gte->trans_vector[0] << 12;
        ty = (int64_t)gte->trans_vector[1] << 12;
        tz = (int64_t)gte->trans_vector[2] << 12;
    } else if (cv_sel == 1) {
        tx = (int64_t)gte->back_color[0] << 12;
        ty = (int64_t)gte->back_color[1] << 12;
        tz = (int64_t)gte->back_color[2] << 12;
    }

    int64_t mac1, mac2, mac3;
    if (cv2_bug) {
        mac1 = (int64_t)m[0][1] * vy + (int64_t)m[0][2] * vz;
        mac2 = (int64_t)m[1][1] * vy + (int64_t)m[1][2] * vz;
        mac3 = (int64_t)m[2][1] * vy + (int64_t)m[2][2] * vz;
    } else {
        mac1 = tx + (int64_t)m[0][0] * vx + (int64_t)m[0][1] * vy + (int64_t)m[0][2] * vz;
        mac2 = ty + (int64_t)m[1][0] * vx + (int64_t)m[1][1] * vy + (int64_t)m[1][2] * vz;
        mac3 = tz + (int64_t)m[2][0] * vx + (int64_t)m[2][1] * vy + (int64_t)m[2][2] * vz;
    }

    check_mac1_overflow(gte, mac1);
    check_mac2_overflow(gte, mac2);
    check_mac3_overflow(gte, mac3);

    gte->mac[1] = (int32_t)(mac1 >> (sf ? 12 : 0));
    gte->mac[2] = (int32_t)(mac2 >> (sf ? 12 : 0));
    gte->mac[3] = (int32_t)(mac3 >> (sf ? 12 : 0));

    gte->ir[1] = clamp_ir1(gte, gte->mac[1], lm);
    gte->ir[2] = clamp_ir2(gte, gte->mac[2], lm);
    gte->ir[3] = clamp_ir3(gte, gte->mac[3], lm);

    if (gte->flag & 0x7F87E000) gte->flag |= (1u << 31);
}

// SQR: Square vector
void ps1_gte_sqr(PS1GTE* gte, uint32_t instruction) {
    gte->flag = 0;
    bool sf = (instruction & (1 << 19)) != 0;

    int64_t mac1 = (int64_t)gte->ir[1] * gte->ir[1];
    int64_t mac2 = (int64_t)gte->ir[2] * gte->ir[2];
    int64_t mac3 = (int64_t)gte->ir[3] * gte->ir[3];

    check_mac1_overflow(gte, mac1);
    check_mac2_overflow(gte, mac2);
    check_mac3_overflow(gte, mac3);

    gte->mac[1] = (int32_t)(mac1 >> (sf ? 12 : 0));
    gte->mac[2] = (int32_t)(mac2 >> (sf ? 12 : 0));
    gte->mac[3] = (int32_t)(mac3 >> (sf ? 12 : 0));

    gte->ir[1] = clamp_ir1(gte, gte->mac[1], true);
    gte->ir[2] = clamp_ir2(gte, gte->mac[2], true);
    gte->ir[3] = clamp_ir3(gte, gte->mac[3], true);

    if (gte->flag & 0x7F87E000) gte->flag |= (1u << 31);
}

// OP: Cross product
void ps1_gte_op(PS1GTE* gte, uint32_t instruction) {
    gte->flag = 0;
    bool sf = (instruction & (1 << 19)) != 0;
    bool lm = (instruction & (1 << 10)) != 0;

    int16_t d1 = gte->rot_matrix[0][0];
    int16_t d2 = gte->rot_matrix[1][1];
    int16_t d3 = gte->rot_matrix[2][2];

    int64_t mac1 = (int64_t)gte->ir[3] * d2 - (int64_t)gte->ir[2] * d3;
    int64_t mac2 = (int64_t)gte->ir[1] * d3 - (int64_t)gte->ir[3] * d1;
    int64_t mac3 = (int64_t)gte->ir[2] * d1 - (int64_t)gte->ir[1] * d2;

    check_mac1_overflow(gte, mac1);
    check_mac2_overflow(gte, mac2);
    check_mac3_overflow(gte, mac3);

    gte->mac[1] = (int32_t)(mac1 >> (sf ? 12 : 0));
    gte->mac[2] = (int32_t)(mac2 >> (sf ? 12 : 0));
    gte->mac[3] = (int32_t)(mac3 >> (sf ? 12 : 0));

    gte->ir[1] = clamp_ir1(gte, gte->mac[1], lm);
    gte->ir[2] = clamp_ir2(gte, gte->mac[2], lm);
    gte->ir[3] = clamp_ir3(gte, gte->mac[3], lm);

    if (gte->flag & 0x7F87E000) gte->flag |= (1u << 31);
}

// Far color interpolation helper: MAC + (FC - MAC) * IR0
static inline void gte_fc_interpolate(PS1GTE* gte, bool sf) {
    int64_t diff1 = (((int64_t)gte->far_color[0] << 12) - gte->mac[1]) >> (sf ? 12 : 0);
    int64_t diff2 = (((int64_t)gte->far_color[1] << 12) - gte->mac[2]) >> (sf ? 12 : 0);
    int64_t diff3 = (((int64_t)gte->far_color[2] << 12) - gte->mac[3]) >> (sf ? 12 : 0);

    gte->ir[1] = clamp_ir1(gte, diff1, false);
    gte->ir[2] = clamp_ir2(gte, diff2, false);
    gte->ir[3] = clamp_ir3(gte, diff3, false);

    int64_t mac1 = ((int64_t)gte->ir[1] * gte->ir[0]) + gte->mac[1];
    int64_t mac2 = ((int64_t)gte->ir[2] * gte->ir[0]) + gte->mac[2];
    int64_t mac3 = ((int64_t)gte->ir[3] * gte->ir[0]) + gte->mac[3];

    check_mac1_overflow(gte, mac1);
    check_mac2_overflow(gte, mac2);
    check_mac3_overflow(gte, mac3);

    gte->mac[1] = (int32_t)mac1;
    gte->mac[2] = (int32_t)mac2;
    gte->mac[3] = (int32_t)mac3;
}

static inline void gte_finish_color_command(PS1GTE* gte, bool sf, bool lm) {
    int64_t shifted1 = gte->mac[1] >> (sf ? 12 : 0);
    int64_t shifted2 = gte->mac[2] >> (sf ? 12 : 0);
    int64_t shifted3 = gte->mac[3] >> (sf ? 12 : 0);

    gte->mac[1] = (int32_t)shifted1;
    gte->mac[2] = (int32_t)shifted2;
    gte->mac[3] = (int32_t)shifted3;

    uint8_t r = clamp_color_r(gte, shifted1 >> 4);
    uint8_t g = clamp_color_g(gte, shifted2 >> 4);
    uint8_t b = clamp_color_b(gte, shifted3 >> 4);
    push_color_fifo(gte, r, g, b, gte->rgbc[3]);

    gte->ir[1] = clamp_ir1(gte, shifted1, lm);
    gte->ir[2] = clamp_ir2(gte, shifted2, lm);
    gte->ir[3] = clamp_ir3(gte, shifted3, lm);
}

void ps1_gte_dpcs(PS1GTE* gte, uint32_t instruction) {
    gte->flag = 0;
    bool sf = (instruction & (1 << 19)) != 0;
    bool lm = (instruction & (1 << 10)) != 0;

    gte->mac[1] = (int64_t)gte->rgbc[0] << 16;
    gte->mac[2] = (int64_t)gte->rgbc[1] << 16;
    gte->mac[3] = (int64_t)gte->rgbc[2] << 16;

    gte_fc_interpolate(gte, sf);
    gte_finish_color_command(gte, sf, lm);

    if (gte->flag & 0x7F87E000) gte->flag |= (1u << 31);
}

void ps1_gte_dpct(PS1GTE* gte, uint32_t instruction) {
    gte->flag = 0;
    bool sf = (instruction & (1 << 19)) != 0;
    bool lm = (instruction & (1 << 10)) != 0;

    for (int i = 0; i < 3; i++) {
        gte->mac[1] = (int64_t)gte->rgb[0][0] << 16;
        gte->mac[2] = (int64_t)gte->rgb[0][1] << 16;
        gte->mac[3] = (int64_t)gte->rgb[0][2] << 16;

        gte_fc_interpolate(gte, sf);
        gte_finish_color_command(gte, sf, lm);
    }

    if (gte->flag & 0x7F87E000) gte->flag |= (1u << 31);
}

