    int64_t mac1 = ((int64_t)gte->mac[1] << (sf ? 12 : 0)) + (int64_t)gte->ir[1] * gte->ir[0];
    int64_t mac2 = ((int64_t)gte->mac[2] << (sf ? 12 : 0)) + (int64_t)gte->ir[2] * gte->ir[0];
    int64_t mac3 = ((int64_t)gte->mac[3] << (sf ? 12 : 0)) + (int64_t)gte->ir[3] * gte->ir[0];

    check_mac1_overflow(gte, mac1);
    check_mac2_overflow(gte, mac2);
